"""Generated by Furnace Forge from app/main.py::chat.

render(question): the exact chat messages the handler sends to the model, without
starting the server or calling the model.
answer(question): the handler's full answer path (model call and any output
post-processing), as text. Needs the app's model endpoint.
Regenerate this file if that handler changes."""

from types import SimpleNamespace

from app.main import build_messages, rag_config, retrieve, stream_answer


def render(question: str) -> list[dict]:
    req = SimpleNamespace(question=question)
    cfg = rag_config()
    chunks = retrieve(req.question, top_k=cfg["retrieval"]["top_k"])
    messages = build_messages(req.question, chunks, cfg["retrieval"]["max_context_chars"])
    return messages


def answer(question: str) -> str:
    req = SimpleNamespace(question=question)
    cfg = rag_config()
    chunks = retrieve(req.question, top_k=cfg["retrieval"]["top_k"])
    messages = build_messages(req.question, chunks, cfg["retrieval"]["max_context_chars"])
    gen = cfg["generation"]
    out = stream_answer(
            messages,
            max_tokens=gen["max_tokens"],
            temperature=gen["temperature"],
            route="/chat",
        )
    return out if isinstance(out, str) else "".join(out)
